<div class="head"><div><h1><?= icon('users') ?> Manage Users</h1><p class="muted">Staff, administrator and customer login accounts.</p></div><?= act_link('add', 'New staff / admin', url('users/create')) ?></div>
<form method="get" class="filter wrap"><input type="hidden" name="r" value="users/index"><input name="q" placeholder="Search username or email" value="<?= e($q) ?>" aria-label="Search"><select name="role" aria-label="Role"><option value="">All roles</option><?php foreach (['admin', 'staff', 'customer'] as $ro): ?><option value="<?= $ro ?>" <?= $role === $ro ? 'selected' : '' ?>><?= ucfirst($ro) ?></option><?php endforeach; ?></select><button class="btn sm">Filter</button></form>
<div class="panel"><div class="tw"><table><tr><th>Username</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr><?php foreach ($rows as $x): ?><tr><td><?= e($x['username']) ?></td><td><?= e($x['email']) ?></td><td><?= e(ucfirst($x['role'])) ?></td><td><?= $x['is_active'] ? badge('Paid') : badge('Unpaid') ?> <small class="muted"><?= $x['is_active'] ? 'Active' : 'Inactive' ?></small></td>
<td class="acts2"><?= act_link('edit', 'Edit', url('users/edit', ['id' => $x['user_id']])) ?><?php if ((int)$x['user_id'] !== $u['id']): ?><?php if ($x['role'] === 'admin'): ?><?= $x['is_active'] ? act_form('warn', 'Deactivate', 'users/setactive', ['id' => $x['user_id'], 'active' => 0], 'Deactivate this account?') : act_form('ok', 'Activate', 'users/setactive', ['id' => $x['user_id'], 'active' => 1], 'Activate this account?') ?><?php elseif ($x['role'] === 'customer'): ?><?= act_form('del', 'Delete', 'users/delete', ['id' => $x['user_id']], 'Delete this customer login? The customer profile and billing history will be kept. Accounts with linked readings or payments cannot be deleted.') ?><?php endif; ?><?php endif; ?></td></tr><?php endforeach; ?></table></div></div>
